/// <summary>
/// Business logic class of  NDXUnitConvertCheck form
/// </summary>
internal final class NDXUnitConvertCheckClass
{
}

Method.Source:
static public void main(Args _args = new Args())
{
    NDXUnitConvert unitConvert;

    if(_args.parmObject() == null || !(_args.parmObject() is NDXUnitConvert))
    {
        throw Error("@NDX:NDXWrongCall");
    }

    unitConvert = _args.parmObject();

    switch(_args.menuItemName())
    {
        case  menuItemActionStr(NDXUnitConvertCheck):
            UnitOfMeasureConversion unitOfMeasureConversion = _args.record();
            unitConvert.checkUnitConvertWeight_DS(unitOfMeasureConversion);
            break;
        case  menuItemDisplayStr(NDXUnitConvertCheckDiff):
            FormRun formrun = new MenuFunction(menuItemDisplayStr(NDXUnitConvertCheckDiff), MenuItemType::Display).create(_args);
            formRun.run();
            formrun.wait();
            break;
    }
}
